    10	    public ClaimOffice(Customer customer) {
    11	        this.policyWideModifiers = new PolicyWideModifiers(customer);
    12	    }
    13	
    14	    /**
    15	     * The policy base premium is the sum of the base premiums of the main items
    16	     * and of the components, each priced by its own MHPCO pricing policy.
    17	     *
    18	     * The MHPCO names this amount in its own rules, so it is observable inside
    19	     * the domain; it is not part of what the office offers a caller, which is
    20	     * a quote.
    21	     */
    22	    int basePremium(List<Item> items) {
    23	        return MainItemPricing.mainItemsBasePremium(items)
    24	                + ComponentPricing.componentsBasePremium(items);
    25	    }
    26	
    27	    /**
    28	     * Item-specific modifiers apply to the base premium of the affected item,
    29	     * not to the policy total.
    30	     */
    31	    BigDecimal premiumAfterItemModifiers(List<Item> items) {
    32	        return BigDecimal.valueOf(basePremium(items))
    33	                .add(ItemRiskSurcharges.totalItemSurcharges(items));
    34	    }
    35	
    36	    /**
    37	     * The MHPCO issues a policy over the items it has agreed to cover.
    38	     */
    39	    public Policy insure(List<Item> items) {
    40	        return new Policy(accepted(items));
    41	    }
