     1	/**
     2	 * The most the MHPCO will pay out over the life of one policy -- twice the
     3	 * insurance sum of the items it covers -- and what is left of it as the office
     4	 * settles claims against that policy.
     5	 *
     6	 * This is the one place that decides the office's payout ceiling and how
     7	 * claims consume it. Both are separate decisions from what the covered items
     8	 * are insured for: the MHPCO may revalue the items it covers without changing
     9	 * how far it will go beyond that value, may change how far it will go without
    10	 * revaluing anything, and may change how a settled claim draws the ceiling
    11	 * down -- a shared balance today, a per-incident sub-limit or a yearly reset
    12	 * tomorrow -- without touching either.
    13	 *
    14	 * A cap is spent as the policy it belongs to is claimed against, so an
    15	 * instance is mutable and belongs to exactly one policy.
    16	 */
    17	public final class PayoutCap {
    18	
    19	    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    20	
    21	    private final int capInG;
    22	
    23	    private int remainingInG;
    24	
    25	    private PayoutCap(int capInG) {
    26	        this.capInG = capInG;
    27	        this.remainingInG = capInG;
    28	    }
    29	
    30	    /**
    31	     * The cap the MHPCO sets over a policy insuring this sum: twice it,
    32	     * entirely unspent.
    33	     */
    34	    public static PayoutCap overInsuranceSum(int insuranceSumInG) {
    35	        return new PayoutCap(CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumInG);
    36	    }
    37	
    38	    /**
    39	     * The whole ceiling, as the MHPCO set it when it issued the policy.
    40	     * Claims settled since do not move it.
    41	     */
    42	    public int total() {
    43	        return capInG;
    44	    }
    45	
    46	    /**
    47	     * What the ceiling has left for further claims.
    48	     */
    49	    public int remaining() {
    50	        return remainingInG;
    51	    }
    52	
    53	    /**
    54	     * The office draws a settlement against the ceiling: it pays what the
    55	     * claimant is owed only as far as the ceiling still reaches, and what it
    56	     * pays is gone from the ceiling for good.
    57	     */
    58	    public int drawDown(int desiredPayoutInG) {
    59	        int paid = Math.min(desiredPayoutInG, remainingInG);
    60	        remainingInG -= paid;
    61	        return paid;
    62	    }
    63	}

     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * What the MHPCO reimburses for reported damage: the amount it reimburses for
     5	 * the damage, less the deductible that applies per damage event.
     6	 *
     7	 * This is the one place that says how much an incident is worth to the
     8	 * claimant. How far the MHPCO will actually go in paying that -- what the
     9	 * policy's cap leaves of it -- is a separate decision, made where the policy
    10	 * settles the claim.
    11	 */
    12	public final class Reimbursement {
    13	
    14	    private static final int DEDUCTIBLE_PER_DAMAGE_IN_G = 100;
    15	
    16	    /**
    17	     * The enchantment level from which the MHPCO reimburses damage at half.
    18	     * It is not the level from which the office charges a high-enchantment
    19	     * risk surcharge on a premium: the office decides what it considers risky
    20	     * enough to charge extra for, and what it considers volatile enough to
    21	     * reimburse only in part, for separate reasons and at separate levels.
    22	     */
    23	    private static final int VOLATILE_ENCHANTMENT_LEVEL = 8;
    24	
    25	    private static final int VOLATILE_ITEM_REIMBURSEMENT_PERCENT = 50;
    26	
    27	    private Reimbursement() {
    28	    }
    29	
    30	    /**
    31	     * An incident is reimbursed damage by damage: the office settles each
    32	     * reported damage on its own and pays the sum, because the deductible is
    33	     * charged per damage event rather than once for the incident.
    34	     *
    35	     * The MHPCO keeps intermediate amounts as fractions and rounds only the
    36	     * final payout, so each damage is settled as a fraction and the sum is
    37	     * rounded to whole G once, here, in the office's favour.
    38	     */
    39	    public static int forIncident(Incident incident, Coverage coverage) {
    40	        return MhpcoFavour.roundedOwedByTheOffice(incident.damages().stream()
    41	                .map(damage -> forDamage(damage, coverage.damagedIn(damage)))
    42	                .reduce(BigDecimal.ZERO, BigDecimal::add));
    43	    }
    44	
    45	    /**
    46	     * One reported damage is settled in two steps the MHPCO decides
    47	     * separately: how much of the damage it reimburses at all, and then the
    48	     * deductible it charges for the damage event.
    49	     */
    50	    private static BigDecimal forDamage(Damage damage, Item damagedItem) {
    51	        return reimbursableAmount(damage, damagedItem)
    52	                .subtract(BigDecimal.valueOf(DEDUCTIBLE_PER_DAMAGE_IN_G));
    53	    }
    54	
    55	    /**
    56	     * How much of a reported damage the MHPCO reimburses, before the
    57	     * deductible: damage to a volatile item is reimbursed at half, anything
    58	     * else in full.
    59	     */
    60	    private static BigDecimal reimbursableAmount(Damage damage, Item damagedItem) {
    61	        if (isVolatile(damagedItem)) {
    62	            return Percentage.of(damage.amount(), VOLATILE_ITEM_REIMBURSEMENT_PERCENT);
    63	        }
    64	        return BigDecimal.valueOf(damage.amount());
    65	    }
    66	
    67	    /**
    68	     * The MHPCO counts an item of enchantment level 8 or more as volatile:
    69	     * too unstable to reimburse in full, whatever it is made of.
    70	     */
    71	    private static boolean isVolatile(Item item) {
    72	        return item.enchantment() >= VOLATILE_ENCHANTMENT_LEVEL;
    73	    }
    74	}
