     * refusal of the whole claim when this policy covers no such item.
     */
    @Override
    public Item damagedIn(Damage damage) {
        return matching(damage).orElseThrow(() -> notCovered(damage));
    }

    /**
     * Which covered item answers to a reported damage: the first one of the
     * damaged type.
     */
    private java.util.Optional<Item> matching(Damage damage) {
